def _trunc_summary(self, trace_text):
    s = str(trace_text)
    lines = s.splitlines()
    err = [ln for ln in lines if ("ERROR" in ln or "AssertionError" in ln)]
    if err:
        return "\n".join(err[-3:])
    return "\n".join(lines[-50:])

